body {
  margin: 0;
  min-height: 100vh;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: #f2f4f8;
  color: #1f2933;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 3rem 1rem;
}

.app {
  width: 100%;
  max-width: 480px;
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  padding: 1.5rem;
}

h1 {
  margin: 0 0 1rem;
  font-size: 1.6rem;
  text-align: center;
}

.todo-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.todo-form input {
  flex: 1;
  padding: 0.6rem 0.8rem;
  font-size: 1rem;
  border: 1px solid #cbd2d9;
  border-radius: 8px;
}

.todo-form input:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 1px;
  border-color: transparent;
}

.todo-form button {
  padding: 0.6rem 1.1rem;
  font-size: 1rem;
  border: none;
  border-radius: 8px;
  background: #3b82f6;
  color: #fff;
  cursor: pointer;
}

.todo-form button:hover {
  background: #2563eb;
}

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.25rem;
  border-bottom: 1px solid #e4e7eb;
}

.todo-item input[type="checkbox"] {
  width: 1.15rem;
  height: 1.15rem;
  cursor: pointer;
  flex-shrink: 0;
}

.todo-item .todo-text {
  flex: 1;
  word-break: break-word;
}

.todo-item.done .todo-text {
  text-decoration: line-through;
  color: #9aa5b1;
}

.delete-btn {
  border: none;
  background: transparent;
  color: #9aa5b1;
  font-size: 1.3rem;
  line-height: 1;
  cursor: pointer;
  padding: 0.2rem 0.45rem;
  border-radius: 6px;
}

.delete-btn:hover,
.delete-btn:focus-visible {
  color: #e12d39;
  background: #fde8e8;
}

.empty-message {
  text-align: center;
  color: #9aa5b1;
  margin: 1rem 0;
}

.empty-message[hidden] {
  display: none;
}

.todo-footer {
  margin-top: 1rem;
  font-size: 0.9rem;
  color: #616e7c;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

