(function () {
  "use strict";

  const STORAGE_KEY = "todo-app.items";

  const form = document.getElementById("todo-form");
  const input = document.getElementById("todo-input");
  const list = document.getElementById("todo-list");
  const countEl = document.getElementById("todo-count");
  const emptyMessage = document.getElementById("empty-message");

  let todos = loadTodos();

  // ----- Storage -----

  function loadTodos() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(
        (t) => t && typeof t.id === "string" && typeof t.text === "string"
      ).map((t) => ({ id: t.id, text: t.text, done: Boolean(t.done) }));
    } catch (err) {
      console.warn("Could not read saved to-dos:", err);
      return [];
    }
  }

  function saveTodos() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (err) {
      console.warn("Could not save to-dos:", err);
    }
  }

  // ----- Actions -----

  function makeId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function addTodo(text) {
    todos.push({ id: makeId(), text: text, done: false });
    commit();
  }

  function toggleTodo(id) {
    const todo = todos.find((t) => t.id === id);
    if (todo) {
      todo.done = !todo.done;
      commit();
    }
  }

  function deleteTodo(id) {
    todos = todos.filter((t) => t.id !== id);
    commit();
  }

  function commit() {
    saveTodos();
    render();
  }

  // ----- Rendering -----

  function createItem(todo) {
    const li = document.createElement("li");
    li.className = "todo-item" + (todo.done ? " done" : "");
    li.dataset.id = todo.id;

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = todo.done;
    checkbox.className = "toggle";
    checkbox.setAttribute("aria-label", "Mark \"" + todo.text + "\" as done");

    const span = document.createElement("span");
    span.className = "todo-text";
    span.textContent = todo.text; // textContent avoids HTML injection

    const del = document.createElement("button");
    del.type = "button";
    del.className = "delete-btn";
    del.textContent = "×";
    del.setAttribute("aria-label", "Delete \"" + todo.text + "\"");

    li.append(checkbox, span, del);
    return li;
  }

  function render() {
    list.replaceChildren(...todos.map(createItem));

    const remaining = todos.filter((t) => !t.done).length;
    countEl.textContent =
      remaining + (remaining === 1 ? " item left" : " items left");

    emptyMessage.hidden = todos.length > 0;
  }

  // ----- Events -----

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    const text = input.value.trim();
    if (!text) {
      input.value = "";
      return;
    }
    addTodo(text);
    input.value = "";
    input.focus();
  });

  // Event delegation: one listener handles all items.
  list.addEventListener("change", function (e) {
    if (e.target.classList.contains("toggle")) {
      toggleTodo(e.target.closest(".todo-item").dataset.id);
    }
  });

  list.addEventListener("click", function (e) {
    const btn = e.target.closest(".delete-btn");
    if (btn) {
      deleteTodo(btn.closest(".todo-item").dataset.id);
    }
  });

  // Keep multiple open tabs in sync.
  window.addEventListener("storage", function (e) {
    if (e.key === STORAGE_KEY) {
      todos = loadTodos();
      render();
    }
  });

  render();
})();

